    "Hyperextensions_Back_Extensions": {
      "id": "Hyperextensions_Back_Extensions",
      "name": "Iperestensioni",
      "nameEn": "Hyperextensions (Back Extensions)",
      "sets": 3,
      "reps": "12-20",
      "rir": "0-1",
      "rest": "60s",
      "isCompound": false,
      "tags": ["CORE", "GLUTE"],
      "badges": [],
      "equip": "Varie",
      "level": "Base",
      "shortNote": "",
      "execution": ["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.", "Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.", "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.", "Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.", "Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.", "Repeat for the recommended amount of repetitions."],
      "cues": "",
      "img": "exercises/Hyperextensions_Back_Extensions/0.webp",
      "lang": "en",
      "img2": "exercises/Hyperextensions_Back_Extensions/1.webp",
      "prof": "MEDIO"
    },
