    "Lying_Machine_Squat": {
      "id": "Lying_Machine_Squat",
      "name": "Squat alla macchina sdraiato",
      "nameEn": "Lying Machine Squat",
      "sets": 4,
      "reps": "6-10",
      "rir": "1-2",
      "rest": "2:30",
      "isCompound": true,
      "tags": ["QUAD", "POLP"],
      "badges": ["C"],
      "equip": "Macchina",
      "level": "Intermedio",
      "shortNote": "",
      "execution": ["Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.", "Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.", "Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.", "While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.", "Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.", "Repeat for the recommended amount of repetitions."],
      "cues": "",
      "img": "exercises/Lying_Machine_Squat/0.webp",
      "lang": "en",
      "img2": "exercises/Lying_Machine_Squat/1.webp",
      "prof": "MEDIO"
    },
