    "Lying_T-Bar_Row": {
      "id": "Lying_T-Bar_Row",
      "name": "Rematore sdraiato t",
      "nameEn": "Lying T-Bar Row",
      "sets": 4,
      "reps": "6-10",
      "rir": "1-2",
      "rest": "2:30",
      "isCompound": true,
      "tags": ["DORSO", "BI"],
      "badges": ["C"],
      "equip": "Macchina",
      "level": "Intermedio",
      "shortNote": "",
      "execution": ["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.", "Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.", "Lift the bar off the rack and extend your arms in front of you. This will be your starting position.", "As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.", "After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.", "Repeat for the recommended amount of repetitions."],
      "cues": "",
      "img": "exercises/Lying_T-Bar_Row/0.webp",
      "lang": "en",
      "img2": "exercises/Lying_T-Bar_Row/1.webp",
      "prof": "MEDIO"
    },
