    "Muscle_Up": {
      "id": "Muscle_Up",
      "name": "Esercizio",
      "nameEn": "Muscle Up",
      "sets": 4,
      "reps": "6-10",
      "rir": "1-2",
      "rest": "2:30",
      "isCompound": true,
      "tags": ["DORSO", "CORE"],
      "badges": ["C"],
      "equip": "Varie",
      "level": "Intermedio",
      "shortNote": "",
      "execution": ["Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.", "As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.", "Maintaining control and stability, extend through the elbow to complete the motion.", "Use care when lowering yourself to the ground."],
      "cues": "",
      "img": "exercises/Muscle_Up/0.webp",
      "lang": "en",
      "img2": "exercises/Muscle_Up/1.webp",
      "prof": "MEDIO"
    },
    "Narrow_Stance_Hack_Squats": {
      "id": "Narrow_Stance_Hack_Squats",
      "name": "Hack squat stretta stance",
      "nameEn": "Narrow Stance Hack Squats",
      "sets": 4,
      "reps": "6-10",
      "rir": "1-2",
      "rest": "2:30",
      "isCompound": true,
      "tags": ["QUAD", "POLP"],
      "badges": ["C"],
      "equip": "Macchina",
      "level": "Intermedio",
      "shortNote": "",
      "execution": ["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.", "Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).", "Now straighten your legs without locking the knees. This will be your starting position.", "Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.", "Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."],
      "cues": "",
      "img": "exercises/Narrow_Stance_Hack_Squats/0.webp",
      "lang": "en",
      "img2": "exercises/Narrow_Stance_Hack_Squats/1.webp",
      "prof": "MEDIO"
    },
    "Narrow_Stance_Leg_Press": {
      "id": "Narrow_Stance_Leg_Press",
      "name": "Leg press stretta stance",
      "nameEn": "Narrow Stance Leg Press",
      "sets": 4,
      "reps": "6-10",
      "rir": "1-2",
      "rest": "2:30",
      "isCompound": true,
      "tags": ["QUAD", "POLP"],
      "badges": ["C"],
      "equip": "Macchina",
      "level": "Intermedio",
      "shortNote": "",
      "execution": ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],
      "cues": "",
      "img": "exercises/Narrow_Stance_Leg_Press/0.webp",
      "lang": "en",
      "img2": "exercises/Narrow_Stance_Leg_Press/1.webp",
      "prof": "MEDIO"
    },
