      "rir": "0-1",
      "rest": "75s",
      "isCompound": false,
      "tags": ["TRI"],
      "badges": [],
      "equip": "Varie",
      "level": "Base",
      "shortNote": "",
      "execution": ["Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.", "Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.", "Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.", "Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability."],
      "cues": "",
      "img": "exercises/Sled_Overhead_Triceps_Extension/0.webp",
