      "shortNote": "",
      "execution": ["For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.", "To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.", "To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.", "Pause, and then return to the starting position."],
