      "execution": ["In piedi con i piedi alla larghezza delle spalle e i talloni sollevati, una mano a un supporto", "Con l'altra mano tieni un disco al petto", "Piega le ginocchia portando il bacino in avanti e il busto indietro, scendendo in linea", "Tieni un secondo in basso, poi risali con la forza dei quadricipiti"],
      "cues": "Se hai avuto problemi al ginocchio, saltalo: l'articolazione qui lavora in una posizione molto esposta.",
