    "Weighted_Sit-Ups_-_With_Bands": {
      "id": "Weighted_Sit-Ups_-_With_Bands",
      "name": "Sit-up con elastici",
      "nameEn": "Weighted Sit-Ups - With Bands",
      "sets": 3,
      "reps": "12-20",
      "rir": "0-1",
      "rest": "60s",
      "isCompound": false,
      "tags": ["CORE"],
      "badges": [],
      "equip": "Varie",
      "level": "Intermedio",
      "shortNote": "",
      "execution": ["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.", "Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.", "Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."],
      "cues": "",
      "img": "exercises/Weighted_Sit-Ups_-_With_Bands/0.webp",
      "lang": "en",
      "img2": "exercises/Weighted_Sit-Ups_-_With_Bands/1.webp",
      "prof": "MEDIO"
    },
    "Weighted_Squat": {
      "id": "Weighted_Squat",
      "name": "Squat zavorrato",
      "nameEn": "Weighted Squat",
      "sets": 4,
      "reps": "6-10",
      "rir": "1-2",
      "rest": "2:30",
      "isCompound": true,
      "tags": ["QUAD", "POLP"],
      "badges": ["C"],
      "equip": "Varie",
      "level": "Intermedio",
      "shortNote": "",
      "execution": ["Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.", "Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.", "Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.", "Repeat for the recommended amount of repetitions."],
      "cues": "",
      "img": "exercises/Weighted_Squat/0.webp",
      "lang": "en",
      "img2": "exercises/Weighted_Squat/1.webp",
      "prof": "MEDIO"
    },
