Object.values(EXERCISE_PACK.exercises).forEach(ex => {
  if (!EXERCISE_DB[ex.id]) EXERCISE_DB[ex.id] = ex; // le schede fatte a mano hanno precedenza
  if (ex.img) EXERCISE_IMAGES[ex.id] = [ex.img].concat(ex.img2 ? [ex.img2] : []);
});
Object.keys(BUILTIN_TWIN).forEach(bid => {
  const t = EXERCISE_PACK.exercises[BUILTIN_TWIN[bid]];
  if (t && t.img) EXERCISE_IMAGES[bid] = [t.img].concat(t.img2 ? [t.img2] : []);
});
